const wanted = ['1 · Oggi', '2 · Rispondere', '3 · In attesa', '4 · Follow-up'];
const byName = {};

for (const item of $input.all()) {
  const name = String(item.json.name ?? '').trim();
  const id = String(item.json.id ?? '').trim();
  if (wanted.includes(name) && id) byName[name] = id;
}

const missing = wanted.filter(name => !byName[name]);
if (missing.length) {
  throw new Error(`Missing Gmail workflow labels: ${missing.join(', ')}. Create them first, then retry.`);
}

return [{
  json: {
    wanted,
    byName,
    allIds: wanted.map(name => byName[name]),
  }
}];

const thread = $json;
const labelCfg = $('Resolve Queue Labels').first().json;
const wanted = labelCfg.wanted;
const byName = labelCfg.byName;
const ownAddresses = [
  'luca@lucaberton.com',
  'luca@lucaberton.it',
  'luca@mrevolution.eu',
];

const messages = Array.isArray(thread.messages) ? [...thread.messages] : [];
if (!messages.length) return [];

messages.sort((a, b) => Number(a.internalDate || 0) - Number(b.internalDate || 0));
const lastInternalDate = String(messages[messages.length - 1]?.internalDate || '');
if (!lastInternalDate) return [];

const state = $getWorkflowStaticData('global');
state.gmailTriageCache = state.gmailTriageCache || {};
const cached = state.gmailTriageCache[String(thread.id || '')];
const isManual = (typeof $execution !== 'undefined' && $execution?.mode === 'manual');
if (!isManual && cached?.lastInternalDate === lastInternalDate) return [];

function header(message, name) {
  const headers = message?.payload?.headers || [];
  const hit = headers.find(h => String(h.name || '').toLowerCase() === name.toLowerCase());
  return String(hit?.value || '');
}

function b64urlDecode(value) {
  if (!value) return '';
  try {
    let s = String(value).replace(/-/g, '+').replace(/_/g, '/');
    while (s.length % 4) s += '=';
    return Buffer.from(s, 'base64').toString('utf8');
  } catch {
    return '';
  }
}

function stripHtml(html) {
  return String(html || '')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]{2,}/g, ' ')
    .trim();
}

function collectBodies(part, out) {
  if (!part) return;
  const mime = String(part.mimeType || '').toLowerCase();
  const data = part?.body?.data;
  if (data && mime === 'text/plain') out.plain.push(b64urlDecode(data));
  if (data && mime === 'text/html') out.html.push(stripHtml(b64urlDecode(data)));
  for (const child of (part.parts || [])) collectBodies(child, out);
}

function messageBody(message) {
  const out = { plain: [], html: [] };
  collectBodies(message?.payload, out);

  let body = out.plain.filter(Boolean).join('\n\n').trim();
  if (!body) body = out.html.filter(Boolean).join('\n\n').trim();
  if (!body) body = String(message?.snippet || '').trim();
  return body.slice(0, 3500);
}

function isMine(from) {
  const f = String(from || '').toLowerCase();
  return ownAddresses.some(addr => f.includes(addr));
}

const threadLabelIds = new Set(
  messages.flatMap(m => Array.isArray(m.labelIds) ? m.labelIds : [])
);
const currentQueue =
  wanted.find(name => threadLabelIds.has(byName[name])) || 'NONE';

const selectedMessages = messages.slice(-10);
const rendered = selectedMessages.map((m, idx) => {
  const from = header(m, 'From');
  const to = header(m, 'To');
  const cc = header(m, 'Cc');
  const subject = header(m, 'Subject');
  const date = header(m, 'Date') || (m.internalDate ? new Date(Number(m.internalDate)).toISOString() : '');
  const body = messageBody(m);
  return [
    `MESSAGE ${idx + 1}/${selectedMessages.length}`,
    `Date: ${date}`,
    `From: ${from}`,
    `To: ${to}`,
    cc ? `Cc: ${cc}` : '',
    `Subject: ${subject}`,
    `Sender is Luca: ${isMine(from) ? 'yes' : 'no'}`,
    `Body:\n${body}`,
  ].filter(Boolean).join('\n');
}).join('\n\n---\n\n').slice(0, 20000);

const latest = messages[messages.length - 1];
const latestFrom = header(latest, 'From');

return [{
  json: {
    thread_id: String(thread.id || latest?.threadId || ''),
    current_queue: currentQueue,
    last_internal_date: lastInternalDate,
    latest_from: latestFrom,
    latest_is_me: isMine(latestFrom),
    message_count: messages.length,
    thread_text: rendered,
  }
}];

