const triage = $('Build Triage Input').item.json;
const response = $json;

function getText(resp) {
  if (!resp) return '';
  if (typeof resp.output_text === 'string') return resp.output_text;
  if (Array.isArray(resp.output)) {
    for (const outputItem of resp.output) {
      if (!Array.isArray(outputItem?.content)) continue;
      for (const part of outputItem.content) {
        if (typeof part?.text === 'string') return part.text;
      }
    }
  }
  if (resp.body) return getText(resp.body);
  return '';
}

const allowed = new Set([
  'NONE',
  '1 · Oggi',
  '2 · Rispondere',
  '3 · In attesa',
  '4 · Follow-up',
]);

let classificationOk = false;
let selectedLabel = 'NONE';
let reason = '';
let nextAction = '';
let confidence = 0;
let error = '';

try {
  const text = getText(response);
  if (!text) throw new Error(response?.error?.message || response?.message || 'OpenAI returned no structured output');
  const ai = JSON.parse(text);

  selectedLabel = allowed.has(ai.selected_label) ? ai.selected_label : 'NONE';
  reason = String(ai.reason || '').trim().slice(0, 600);
  nextAction = String(ai.next_action || '').trim().slice(0, 400);
  confidence = Number(ai.confidence);
  if (!Number.isFinite(confidence)) confidence = 0;
  confidence = Math.max(0, Math.min(1, confidence));
  classificationOk = true;
} catch (e) {
  error = String(e?.message || e).slice(0, 600);
}

const labelCfg = $('Resolve Queue Labels').first().json;
const selectedLabelId = selectedLabel === 'NONE' ? '' : String(labelCfg.byName[selectedLabel] || '');

const safeToChange = classificationOk && confidence >= 0.72;
const needsChange = safeToChange && selectedLabel !== triage.current_queue;

return [{
  json: {
    ...triage,
    selected_label: selectedLabel,
    selected_label_id: selectedLabelId,
    confidence,
    reason,
    next_action: nextAction,
    classification_ok: classificationOk,
    safe_to_change: safeToChange,
    needs_change: needsChange,
    error,
  }
}];

const classified = $('Parse Classification').item.json;
if (!classified.classification_ok) return [{ json: classified }];

const state = $getWorkflowStaticData('global');
state.gmailTriageCache = state.gmailTriageCache || {};
state.gmailTriageCache[classified.thread_id] = {
  lastInternalDate: classified.last_internal_date,
  seenAt: Date.now(),
  selectedLabel: classified.selected_label,
  confidence: classified.confidence,
};

const cutoff = Date.now() - 30 * 24 * 60 * 60 * 1000;
for (const [threadId, entry] of Object.entries(state.gmailTriageCache)) {
  if (!entry?.seenAt || Number(entry.seenAt) < cutoff) delete state.gmailTriageCache[threadId];
}

return [{ json: classified }];
